const conteudo = items[0].json.output || "";
let jsonString = "";

try {
  // [TECHNICAL DEBT PAGO] Regex caça apenas o que está entre colchetes ou chaves
  const match = conteudo.match(/(\[[\s\S]*\]|\{[\s\S]*\})/);

  if (!match) throw new Error("Nenhum padrão JSON encontrado.");
  jsonString = match[0];

  // SANITIZADOR SÊNIOR: Arranca zeros à esquerda de números (ex: "dia": 01 vira "dia": 1)
  jsonString = jsonString.replace(/:\s*0+(\d+)/g, ': $1');

  let parsedData = JSON.parse(jsonString);
  if (!Array.isArray(parsedData)) parsedData = [parsedData]; // Força ser matriz
  let saidaFinal = [];

  parsedData.forEach(item => {
    let parcelas = item.parcelas || 1;

    // Se for à vista, joga direto pra saída
    if (parcelas === 1) {
      saidaFinal.push(item);
    } 
    // Se for parcelado, inicia o motor de particionamento
    else {
      let valorParcela = (item.valor / parcelas).toFixed(2);
      let mesBase = parseInt(item.mes_num);
      let anoBase = parseInt(item.ano || new Date().getFullYear());

      for (let i = 1; i <= parcelas; i++) {
        let mesAtual = mesBase + i - 1;
        let anoAtual = anoBase;

        // Se passar de dezembro, vira o ano e reseta o mês
        if (mesAtual > 12) {
          anoAtual += Math.floor((mesAtual - 1) / 12);
          mesAtual = ((mesAtual - 1) % 12) + 1;
        }

        // Clona o objeto e sobrescreve com os dados da parcela atual
        let novaParcela = { ...item };
        novaParcela.valor = parseFloat(valorParcela);
        novaParcela.descricao = `${item.descricao} (${i}/${parcelas})`;
        novaParcela.mes_num = mesAtual.toString().padStart(2, '0');
        novaParcela.ano = anoAtual;

        saidaFinal.push(novaParcela);
      }
    }
  });

  return saidaFinal.map(p => ({ json: p }));

} catch (erro) {
  // Se mesmo com o Regex der pau, cospe o erro no log
  throw new Error("Falha crítica no Parser JSON. IA mandou: " + conteudo);
}

// 1. Pega em todas as linhas do Sheets e na resposta do Agente 1
const todosItens = $input.all();
const porteiroTexto = $('AI Agent1').first().json.output || "{}";

// 2. Extrai os parâmetros dinâmicos da IA (Filtro Ligeiro)
let filtros = { data_inicio: "2000-01-01", data_fim: "2100-12-31" };
try {
  const match = porteiroTexto.match(/\{[\s\S]*\}/);
  if (match) filtros = Object.assign(filtros, JSON.parse(match[0]));
} catch (e) {
  // Fallback silencioso se a IA se engasgar
}

// 3. Conversor de Datas (DD/MM/YYYY do Sheets para YYYY-MM-DD)
function formatarDataParaIso(dataStr) {
  if (!dataStr || !dataStr.includes("/")) return "1970-01-01";
  const partes = dataStr.split("/");
  const dia = partes[0].padStart(2, '0');
  const mes = partes[1].padStart(2, '0');
  let ano = partes[2];
  if (ano.length === 2) ano = "20" + ano; // Cobre anos tipo "26"
  return `${ano}-${mes}-${dia}`;
}

const dataInicioISO = filtros.data_inicio || "2000-01-01";
const dataFimISO = filtros.data_fim || "2100-12-31";

// 4. Filtra o lixo E aplica o range de datas
const itensValidos = todosItens.filter(item => {
  const d = item.json;
  const dataOriginal = d["Data"] || d["dia"];
  const valor = d["Valor"] || d["valor"];

  // Se for linha fantasma (sem valor nem data), dropa já
  if (!dataOriginal && !valor) return false;

  // Compara a data da linha com o pedido do utilizador
  const dataLinhaISO = formatarDataParaIso(dataOriginal);
  return dataLinhaISO >= dataInicioISO && dataLinhaISO <= dataFimISO;
});

// 5. Trava de Segurança HA (Anti-Infarto da Groq)
// Se pedires "tudo desde 2010", limitamos aos últimos 100 para não estourar tokens
const items = itensValidos.slice(-100);

// 6. Formatador Clean
const linhas = items.map(item => {
  const d = item.json;
  const data = d["Data"] || d["dia"] || "S/D";
  const valor = d["Valor"] || d["valor"] || d["col_8"] || 0;
  const desc = d["Descrição"] || d["Descricao"] || "Sem descrição";

  return `- [${data}] ${desc} | R$ ${valor}`;
}).join("\n");

return [{
  json: {
    relatorio_completo: linhas || "Nenhum lançamento encontrado neste período temporal específico."
  }
}];

// Puxa todos os itens que saíram do Google Sheets
const itens = $input.all();
const qtd = itens.length;
const base = itens[0].json;

// Pega as chaves com os nomes exatos das colunas do Sheets
const descricao = base["Descrição"] || "Sem descrição";
const valor = parseFloat(base["Valor"]) || 0;
const tipo = base["Tipo"] || "Geral";
const formaPagamento = base["Forma_Pagamento"] || "N/A";
const quem = base["Responsável."] || base["Responsável"] || "N/A";

let mensagem = "";

if (qtd === 1) {
  // Lançamento Único (Agora usando <b> para negrito)
  mensagem = `✅ <b>Lançamento Confirmado!</b>\n🛒 ${descricao}\n💸 Valor: R$ ${valor.toFixed(2)}\n🏷️ Categoria: ${tipo}\n💳 Tipo: ${formaPagamento}\n👤 Quem: ${quem}`;
} else {
  // Lançamento Múltiplo (Parcelado ou Dividido)
  let descricaoLimpa = descricao.replace(/\s\(\d+\/\d+\)$/, "");
  let valorTotal = itens.reduce((acc, item) => acc + (parseFloat(item.json["Valor"]) || 0), 0);

  mensagem = `✅ <b>Lançamento Múltiplo Confirmado!</b>\n🛒 Item: ${descricaoLimpa}\n💸 Valor Total: R$ ${valorTotal.toFixed(2)}\n🔢 Parcelas/Divisões: ${qtd}x de R$ ${valor.toFixed(2)}\n💳 Tipo: ${formaPagamento}\n👤 Quem: ${quem}`;
}

// Retorna o pacote pronto
return [{
  json: {
    texto_notificacao: mensagem
  }
}];
